{
  "decision-export-rotation-counter-increments": "WITH increments AS (SELECT player_code, rotation_no, tick_no, touch_count - LAG(touch_count, 1, 0) OVER (PARTITION BY player_code COLLATE BINARY, rotation_no ORDER BY tick_no) AS new_touches FROM touch_readings) SELECT 'player,rotation,tick,new_touches' || char(10) || group_concat(line, '') AS csv_body FROM (SELECT player_code || ',' || rotation_no || ',' || tick_no || ',' || new_touches || char(10) AS line FROM increments ORDER BY player_code COLLATE BINARY, rotation_no, tick_no);",
  "decision-export-trip-advance-clearing-csv": "WITH balances AS (SELECT a.trip_code, COALESCE(SUM(e.amount_cents), 0) - a.advance_cents AS balance FROM trip_account AS a LEFT JOIN trip_entry AS e ON e.trip_code COLLATE BINARY = a.trip_code AND e.entry_kind IN ('expense', 'return') WHERE a.phase = 'closed' GROUP BY a.trip_code COLLATE BINARY, a.advance_cents) SELECT 'trip_code,direction,amount_cents' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_body FROM (SELECT '\"' || replace(trip_code, '\"', '\"\"') || '\",' || CASE WHEN balance > 0 THEN 'PAY' ELSE 'COLLECT' END || ',' || abs(balance) || char(10) AS line FROM balances WHERE balance <> 0 ORDER BY trip_code COLLATE BINARY);",
  "decision-export-unfulfilled-partner-kit-orders": "WITH shipped AS (SELECT request_id, SUM(kits_sent) AS kits_sent FROM kit_dispatch GROUP BY request_id), totals AS (SELECT r.partner_label, SUM(MAX(0, r.kits_ordered - COALESCE(s.kits_sent, 0))) AS kits FROM kit_request AS r LEFT JOIN shipped AS s ON s.request_id = r.request_id GROUP BY r.partner_label COLLATE BINARY) SELECT 'partner,kits' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_contents FROM (SELECT '\"' || replace(partner_label, '\"', '\"\"') || '\",' || kits || char(10) AS line FROM totals WHERE kits > 0 ORDER BY partner_label COLLATE BINARY);",
  "decision-export-walkthrough-confirmed-sign-defects": "WITH defects AS (SELECT sign_code, obs_id, round_code FROM sign_observations WHERE finding = 'defect'), pairs AS (SELECT a.sign_code, a.obs_id AS first_obs, b.obs_id AS second_obs, ROW_NUMBER() OVER (PARTITION BY a.sign_code COLLATE BINARY ORDER BY a.obs_id COLLATE BINARY, b.obs_id COLLATE BINARY) AS pair_rank FROM defects AS a JOIN defects AS b ON a.sign_code COLLATE BINARY = b.sign_code AND a.round_code COLLATE BINARY <> b.round_code AND a.obs_id COLLATE BINARY < b.obs_id) SELECT 'sign_code,first_obs,second_obs' || char(10) || COALESCE(group_concat(line, ''), '') AS csv_content FROM (SELECT '\"' || replace(sign_code, '\"', '\"\"') || '\",\"' || replace(first_obs, '\"', '\"\"') || '\",\"' || replace(second_obs, '\"', '\"\"') || '\"' || char(10) AS line FROM pairs WHERE pair_rank = 1 ORDER BY sign_code COLLATE BINARY);"
}
